const boReadingPhrasePattern = new RegExp(Object.keys(boReadingPhrases)
  .sort((a, b) => b.length - a.length).join("|"), "g");

const boReadingShortTerms = {
  BA: ["Building Authority", "建築事務監督"],
  AP: ["Authorized Person", "認可人士"],
  RSE: ["Registered Structural Engineer", "註冊結構工程師"],
  RGE: ["Registered Geotechnical Engineer", "註冊岩土工程師"],
  RI: ["Registered Inspector", "註冊檢驗人員"],
  RGBC: ["Registered General Building Contractor", "註冊一般建築承建商"],
  RSC: ["Registered Specialist Contractor", "註冊專門承建商"],
};
const boReadingTermPattern = /\b(?:(?<english>[A-Z][A-Za-z-]*(?: [A-Z][A-Za-z-]*)*)\s*（(?<chinese>[\u3400-\u9FFF]+)(?:，(?<explicit>[A-Z]{2,4}))?）|(?<abbr>BA|AP|RSE|RGE|RI|RGBC|RSC)\b)/g;

function formatProvisionReading(section, entries) {
  const mentions = new Map();
  const labelCounts = new Map();
  return entries.map(([label, source]) => {
    const occurrence = labelCounts.get(label) ?? 0;
    labelCounts.set(label, occurrence + 1);
    // Scope bilingual repetitions to a subsection, including when only one paragraph is shown.
    const scope = label.match(/^\([\dA-Za-z]+\)/)?.[0] ?? label.split(/[｜(]/, 1)[0];
    if (!mentions.has(scope)) mentions.set(scope, new Set());
    const seen = mentions.get(scope);
    const rawEdit = boReadingEdits[section]?.[label];
    const edited = Array.isArray(rawEdit) ? rawEdit[occurrence] : rawEdit;
    const text = (edited ?? source.replace(boReadingPhrasePattern, phrase => boReadingPhrases[phrase])
      .replace(/^凡係(?=(?:Building Authority|任何|建築事務監督|根據|在|喺|由))/u, "如果")
      .replace(/([，；])就就(?=第)/gu, "$1就"))
      .replace(boReadingTermPattern, (full, english, chinese, explicit, abbr) => {
        if (abbr) {
          const [long, translation] = boReadingShortTerms[abbr];
          if (seen.has(long)) return full;
          seen.add(long);
          return `${long}（${translation}，${abbr}）`;
        }
        if (seen.has(english)) return explicit ?? chinese;
        seen.add(english);
        return full;
      });
    return { label, text };
  });
}
